export function getBusinessForStop(tourId, stopId) {
  return businessPartners.find(
    business => business.relatedTourIds.includes(tourId) && business.relatedStopIds.includes(stopId)
  );
}

export function getOfferForBusiness(businessId) {
  return offers.find(offer => offer.businessId === businessId);
}

export function getLoyaltyProgramForBusiness(businessId) {
  return loyaltyPrograms.find(program => program.businessId === businessId);
}
